/**
 * @param {number[]} nums
 * @return {number}
 */
var missingInteger = function(nums) {
    let sum = nums[0];

    for (let j = 1; j < nums.length; j++) {
        if (nums[j - 1] + 1 !== nums[j]) {
            break;
        }

        sum += nums[j];
    }

    const set = new Set(nums);

    while (set.has(sum)) {
        sum++;
    }

    return sum;
};
